DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260708071912_InitialPostgres') THEN
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (101, 'How do you handle two-way exchange of information?', 'Bạn xử lý việc trao đổi thông tin hai chiều thế nào?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (102, 'What most affects your listening habits?', 'Thói quen lắng nghe của bạn bị ảnh hưởng nhiều nhất bởi gì?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (103, 'How do you deal with differences in wording and terminology?', 'Bạn xử lý sự khác biệt về từ ngữ, thuật ngữ thế nào?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (104, 'What is your texting/email style like?', 'Phong cách viết tin nhắn/email của bạn thế nào?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (105, 'When criticized in a conversation, what is your natural reaction?', 'Khi bị chỉ trích trong hội thoại, phản ứng tự nhiên của bạn là gì?', 1, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (106, 'How do you adapt your communication style to context?', 'Bạn thích ứng phong cách giao tiếp theo bối cảnh thế nào?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (107, 'How do you recognize your own direct/indirect style?', 'Bạn nhận diện phong cách trực tiếp/gián tiếp của mình ra sao?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (108, 'How do you control your body language?', 'Bạn kiểm soát ngôn ngữ cơ thể của mình thế nào?', 1, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (201, 'A team member isn''t contributing to a group project. You...', 'Một thành viên không đóng góp cho dự án nhóm. Bạn...', 2, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (202, 'When your idea conflicts with a teammate''s, you...', 'Khi ý tưởng của bạn xung đột với đồng đội, bạn...', 2, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (203, 'The team hits a setback close to a deadline. You...', 'Nhóm gặp trục trặc sát hạn chót. Bạn...', 2, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (204, 'How do you treat credit for a shared success?', 'Bạn ứng xử với công lao của một thành công chung thế nào?', 2, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (205, 'A quieter teammate hasn''t shared their opinion. You...', 'Một đồng đội trầm tính chưa nêu ý kiến. Bạn...', 2, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (206, 'When you receive a task you dislike but the team needs, you...', 'Khi nhận việc mình không thích nhưng nhóm cần, bạn...', 2, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (207, 'Two teammates are in conflict and it''s slowing work. You...', 'Hai đồng đội mâu thuẫn làm chậm công việc. Bạn...', 2, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (208, 'How reliable are you with commitments to the team?', 'Bạn giữ cam kết với nhóm đáng tin đến đâu?', 2, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (301, 'How does your out-of-class studying go?', 'Việc học ngoài giờ lên lớp của bạn diễn ra thế nào?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (302, 'When you procrastinate on a big task, what is the deepest reason?', 'Khi trì hoãn một việc lớn, lý do sâu xa nhất của bạn là gì?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (303, 'Do you estimate how long a task takes accurately?', 'Bạn ước lượng thời gian làm một việc có chính xác không?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (304, 'What most affects your focus?', 'Yếu tố nào ảnh hưởng đến sự tập trung của bạn nhất?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (305, 'Do you apply scientific time-management methods?', 'Bạn có áp dụng phương pháp quản lý thời gian khoa học không?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (306, 'What do you base on when deciding what to do first?', 'Bạn quyết định làm việc gì trước dựa trên điều gì?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (307, 'How are your study/work goals written?', 'Mục tiêu học tập/công việc của bạn được viết ra như thế nào?', 3, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (308, 'When your plan is broken by an unexpected event, how do you react?', 'Khi kế hoạch bị phá vỡ bởi biến cố bất ngờ, bạn phản ứng ra sao?', 3, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (401, 'How well do you separate fact from personal opinion?', 'Bạn phân biệt sự thật và ý kiến cá nhân tốt đến đâu?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (402, 'How do you deal with your own confirmation bias?', 'Bạn đối phó với thiên kiến xác nhận của bản thân thế nào?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (403, 'In a group debate, how do you usually react?', 'Khi tranh luận nhóm, bạn thường phản ứng ra sao?', 4, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (404, 'How do you verify an unfamiliar source online?', 'Bạn kiểm chứng một nguồn tin lạ trên mạng ra sao?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (405, 'Facing a complex problem, how do you find a solution?', 'Khi gặp vấn đề phức tạp, bạn tìm giải pháp thế nào?', 4, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (406, 'Are you willing to change your view when new evidence appears?', 'Bạn có sẵn sàng thay đổi quan điểm khi có bằng chứng mới không?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (407, 'How do you assess the reliability of a research document?', 'Bạn đánh giá độ tin cậy một tài liệu nghiên cứu ra sao?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (408, 'When facing a problem, do you prepare multiple options?', 'Khi gặp vấn đề, bạn có chuẩn bị nhiều phương án không?', 4, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (501, 'You hit an unfamiliar problem with no obvious solution. You...', 'Bạn gặp một vấn đề lạ không có giải pháp rõ ràng. Bạn...', 5, 1);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (502, 'When a solution fails, you...', 'Khi một giải pháp thất bại, bạn...', 5, 0);
    INSERT INTO "AssessmentQuestions" ("Id", "QuestionText", "QuestionTextVi", "SkillId", "Type")
    VALUES (503, 'A problem is too big to tackle at once. You...', 'Một vấn đề quá lớn để xử lý một lần. Bạn...', 5, 1);
