    VALUES (6033, 'Let the anxiety stall your work.', 'Để nỗi lo làm đình trệ công việc.', 603, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6034, 'Vent to everyone around you.', 'Trút bực dọc lên mọi người xung quanh.', 603, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6041, 'Very — I can name what I feel and why.', 'Rất rõ — tôi gọi tên được cảm xúc và lý do.', 604, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6042, 'Somewhat aware in the moment.', 'Nhận biết phần nào trong lúc đó.', 604, 3);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6043, 'I notice only after the fact.', 'Chỉ nhận ra sau khi mọi chuyện qua.', 604, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6044, 'Rarely aware.', 'Hiếm khi nhận biết.', 604, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6051, 'Acknowledge how they feel and offer support.', 'Ghi nhận cảm xúc của họ và đề nghị hỗ trợ.', 605, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6052, 'Give practical advice right away.', 'Đưa lời khuyên thực tế ngay.', 605, 3);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6053, 'Avoid them to not make it worse.', 'Tránh họ để không làm mọi việc tệ hơn.', 605, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6054, 'Tell them to calm down.', 'Bảo họ bình tĩnh lại.', 605, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6061, 'Process it, learn, and move forward.', 'Xử lý nó, rút kinh nghiệm và tiến lên.', 606, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6062, 'Distract myself and avoid it.', 'Làm mình sao nhãng và né tránh.', 606, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6063, 'Dwell on it for a long time.', 'Day dứt về nó rất lâu.', 606, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6064, 'Let it affect everything else.', 'Để nó ảnh hưởng đến mọi thứ khác.', 606, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6071, 'Regulate your tone and stay constructive.', 'Điều tiết giọng điệu và giữ tinh thần xây dựng.', 607, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6072, 'Go quiet and disengage.', 'Im lặng và rút lui.', 607, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6073, 'Let the frustration show sharply.', 'Để sự bực bội lộ ra gay gắt.', 607, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6074, 'Make a sarcastic comment.', 'Buông một lời mỉa mai.', 607, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6081, 'Stay calm and help de-escalate.', 'Giữ bình tĩnh và giúp hạ nhiệt.', 608, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6082, 'Match their energy without thinking.', 'Bị cuốn theo cảm xúc của họ mà không nghĩ.', 608, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6083, 'Withdraw from the situation.', 'Rút khỏi tình huống.', 608, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (6084, 'Get overwhelmed.', 'Bị choáng ngợp.', 608, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7011, 'Re-assess, adjust the plan, and move forward.', 'Đánh giá lại, điều chỉnh kế hoạch và tiến lên.', 701, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7012, 'Resist the change and argue for the old plan.', 'Chống lại thay đổi và bảo vệ kế hoạch cũ.', 701, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7013, 'Feel stuck and wait for direction.', 'Thấy bế tắc và chờ chỉ đạo.', 701, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7014, 'Keep working on the outdated plan.', 'Vẫn làm theo kế hoạch đã lỗi thời.', 701, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7021, 'I seek them out and enjoy the challenge.', 'Tôi chủ động tìm và thích thử thách.', 702, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7022, 'I''ll learn them when required.', 'Tôi học khi bắt buộc.', 702, 3);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7023, 'I prefer to stick with what I know.', 'Tôi thích giữ những gì đã quen.', 702, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7024, 'I avoid change whenever possible.', 'Tôi né tránh thay đổi bất cứ khi nào có thể.', 702, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7031, 'Stay open, ask questions, and adapt quickly.', 'Giữ cởi mở, đặt câu hỏi và thích nghi nhanh.', 703, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7032, 'Wait for everything to be explained.', 'Chờ mọi thứ được giải thích.', 703, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7033, 'Compare it unfavorably to the old team.', 'So sánh theo hướng chê so với nhóm cũ.', 703, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7034, 'Disengage until things settle.', 'Thu mình lại đến khi mọi việc ổn định.', 703, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7041, 'An opportunity to find a better path.', 'Một cơ hội để tìm hướng đi tốt hơn.', 704, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7042, 'An annoyance I have to tolerate.', 'Một sự phiền toái phải chịu đựng.', 704, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7043, 'A reason to feel discouraged.', 'Một lý do để nản lòng.', 704, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7044, 'A disaster I can''t handle.', 'Một thảm họa tôi không xử lý nổi.', 704, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7051, 'Explore alternatives and learn a replacement.', 'Tìm giải pháp thay thế và học công cụ mới.', 705, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7052, 'Keep using it until it fully breaks.', 'Dùng tiếp đến khi nó hỏng hẳn.', 705, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7053, 'Wait for someone to choose a replacement.', 'Chờ người khác chọn công cụ thay thế.', 705, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7054, 'Complain and delay adapting.', 'Than phiền và trì hoãn thích nghi.', 705, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7061, 'Consider it seriously and try adjusting.', 'Cân nhắc nghiêm túc và thử điều chỉnh.', 706, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7062, 'Consider it but rarely change.', 'Cân nhắc nhưng hiếm khi thay đổi.', 706, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7063, 'Feel criticized and defend my way.', 'Thấy bị chê và bảo vệ cách của mình.', 706, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7064, 'Dismiss it.', 'Gạt bỏ nó.', 706, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7071, 'Stay flexible and re-focus on what matters now.', 'Giữ linh hoạt và tập trung lại vào việc quan trọng lúc này.', 707, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7072, 'Get frustrated but comply.', 'Bực bội nhưng vẫn làm theo.', 707, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7073, 'Push back on every change.', 'Phản đối mọi thay đổi.', 707, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7074, 'Lose motivation.', 'Mất động lực.', 707, 1);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7081, 'Stay calm and take sensible next steps.', 'Giữ bình tĩnh và thực hiện các bước hợp lý tiếp theo.', 708, 4);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7082, 'Wait for full certainty before acting.', 'Chờ hoàn toàn chắc chắn mới hành động.', 708, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7083, 'Feel paralyzed by the unknown.', 'Bị tê liệt trước điều chưa biết.', 708, 2);
    INSERT INTO "AssessmentOptions" ("Id", "OptionText", "OptionTextVi", "QuestionId", "ScoreValue")
    VALUES (7084, 'Act rashly without thinking.', 'Hành động hấp tấp mà không suy nghĩ.', 708, 1);
