    PERFORM setval(
        pg_get_serial_sequence('"Mentors"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Mentors") + 1,
            nextval(pg_get_serial_sequence('"Mentors"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Skills"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Skills") + 1,
            nextval(pg_get_serial_sequence('"Skills"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"AssessmentQuestions"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "AssessmentQuestions") + 1,
            nextval(pg_get_serial_sequence('"AssessmentQuestions"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"CaseStudies"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "CaseStudies") + 1,
            nextval(pg_get_serial_sequence('"CaseStudies"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"AssessmentOptions"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "AssessmentOptions") + 1,
            nextval(pg_get_serial_sequence('"AssessmentOptions"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"CaseStudyOptions"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "CaseStudyOptions") + 1,
            nextval(pg_get_serial_sequence('"CaseStudyOptions"', 'Id'))),
        false);
    END IF;
