DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715183355_AddChatSessions') THEN
    CREATE TABLE "ChatSessions" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "TitleVi" character varying(120) NOT NULL,
        "TitleEn" character varying(120) NOT NULL,
        "CreatedAt" timestamp without time zone NOT NULL,
        "UpdatedAt" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_ChatSessions" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ChatSessions_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715183355_AddChatSessions') THEN
    CREATE INDEX "IX_ChatMessages_ChatSessionId" ON "ChatMessages" ("ChatSessionId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715183355_AddChatSessions') THEN
    CREATE INDEX "IX_ChatSessions_UserId" ON "ChatSessions" ("UserId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260715183355_AddChatSessions') THEN
    INSERT INTO "ChatSessions" ("UserId", "TitleVi", "TitleEn", "CreatedAt", "UpdatedAt")
    SELECT "UserId", 'Lịch sử trước đây', 'Previous conversation', MIN("CreatedAt"), MAX("CreatedAt")
    FROM "ChatMessages"
    WHERE "ChatSessionId" IS NULL
    GROUP BY "UserId";

    UPDATE "ChatMessages" AS message
    SET "ChatSessionId" = session."Id"
    FROM "ChatSessions" AS session
    WHERE message."ChatSessionId" IS NULL AND session."UserId" = message."UserId";
    END IF;
END $EF$;

DO $EF$
