    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261012021518_UseSoftSyncMentors') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Mentors"', 'Id'),
