DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022100000_AddAdminAnalyticsGemini') THEN
    CREATE TABLE "AiProviderSettings" (
        "Id" integer PRIMARY KEY, "Enabled" boolean NOT NULL,
        "ChatModel" character varying(100) NOT NULL, "CvModel" character varying(100) NOT NULL,
        "EvaluationModel" character varying(100) NOT NULL, "Version" integer NOT NULL,
        "UpdatedAtUtc" timestamp with time zone NOT NULL, "UpdatedByUserId" integer NULL);
    CREATE TABLE "AiApiCredentials" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Name" character varying(80) NOT NULL,
        "ProtectedKey" text NOT NULL, "Fingerprint" character varying(12) NOT NULL,
        "QuotaGroup" character varying(80) NOT NULL, "Priority" integer NOT NULL, "Enabled" boolean NOT NULL,
        "CooldownUntilUtc" timestamp with time zone NULL, "LastStatus" character varying(40) NOT NULL,
        "LastMessage" character varying(200) NOT NULL, "LastUsedAtUtc" timestamp with time zone NULL,
        "LastCheckedAtUtc" timestamp with time zone NULL);
    CREATE TABLE "AiOperations" (
        "Id" uuid PRIMARY KEY, "Task" character varying(40) NOT NULL, "Model" character varying(100) NOT NULL,
        "Status" character varying(40) NOT NULL, "AttemptCount" integer NOT NULL, "CredentialId" integer NULL, "InputTokens" bigint NULL,
        "OutputTokens" bigint NULL, "DurationMs" bigint NOT NULL, "CreatedAtUtc" timestamp with time zone NOT NULL);
    CREATE TABLE "SystemMetricMinutes" (
        "MinuteStartUtc" timestamp with time zone NOT NULL, "InstanceId" character varying(100) NOT NULL,
        "AverageCpuPercent" double precision NULL, "PeakCpuPercent" double precision NULL,
        "PeakWorkingSetBytes" bigint NULL, "CpuSampleCount" integer NOT NULL, "RequestCount" bigint NOT NULL,
        "ErrorCount" bigint NOT NULL, "RequestDurationTotalMs" double precision NOT NULL,
        "LatencyBucketsJson" text NOT NULL, PRIMARY KEY ("MinuteStartUtc", "InstanceId"));
    CREATE TABLE "LearningActivitySessions" (
        "Id" uuid PRIMARY KEY, "UserId" integer NOT NULL, "ActivityType" character varying(80) NOT NULL,
        "ResourceId" character varying(120) NOT NULL, "StartedAtUtc" timestamp with time zone NOT NULL,
        "LastHeartbeatAtUtc" timestamp with time zone NOT NULL, "EndedAtUtc" timestamp with time zone NULL,
        "MeasuredSeconds" integer NOT NULL);
    CREATE TABLE "LearningHeartbeats" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "SessionId" uuid NOT NULL,
        "Sequence" integer NOT NULL, "FromUtc" timestamp with time zone NOT NULL, "ToUtc" timestamp with time zone NOT NULL,
        "AcceptedAtUtc" timestamp with time zone NOT NULL, "CreditedSeconds" integer NOT NULL);
    CREATE INDEX "IX_AiApiCredentials_Priority_Enabled" ON "AiApiCredentials" ("Priority", "Enabled");
    CREATE INDEX "IX_AiOperations_CreatedAtUtc_Task_Status" ON "AiOperations" ("CreatedAtUtc", "Task", "Status");
    CREATE INDEX "IX_LearningActivitySessions_UserId_StartedAtUtc" ON "LearningActivitySessions" ("UserId", "StartedAtUtc");
    CREATE UNIQUE INDEX "IX_LearningHeartbeats_SessionId_Sequence" ON "LearningHeartbeats" ("SessionId", "Sequence");
    END IF;
END $EF$;

